def send_pose(robot, xyz, quat_wxyz, gripper):
    """Send one fingertip-centre target to an already connected Robot client."""
    row = [*xyz, *quat_wxyz, float(gripper)]
    return robot.submit("ee_pose", np.asarray([row], dtype=np.float32))


def wait_for_gripper(robot, seconds=1.5):
    """Hold the last command stationary so the Robotiq has time to close."""
    return robot.get_obs(seconds=float(seconds), video="none")


